use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use jsonwebtoken::{decode, DecodingKey, Validation, Algorithm, Header};
use serde::{Deserialize, Serialize};
use sqlx::postgres::PgPoolOptions;
use sqlx::PgPool;
use std::env;

#[derive(Debug, Serialize, Deserialize, Clone)]
struct Claims {
    sub: String,
    tenant_id: String,
    role: String,
    exp: usize,
}

struct AppState {
    db_pool: PgPool,
    jwt_secret: String,
    rsa_public_key: Vec<u8>,
}

fn decode_token(token: &str, state: &AppState) -> Result<Claims, String> {
    // Decode header to determine algorithm
    let header = jsonwebtoken::decode_header(token)
        .map_err(|e| format!("Header decode error: {}", e))?;

    let claims = match header.alg {
        Algorithm::RS256 => {
            let key = DecodingKey::from_rsa_pem(&state.rsa_public_key)
                .map_err(|e| format!("RSA key error: {}", e))?;
            let mut validation = Validation::new(Algorithm::RS256);
            validation.validate_exp = true;
            decode::<Claims>(token, &key, &validation)
                .map_err(|e| format!("RS256 decode error: {}", e))?
        }
        Algorithm::HS256 => {
            // Also support HMAC for internal service-to-service calls
            let key = DecodingKey::from_secret(state.jwt_secret.as_bytes());
            let mut validation = Validation::new(Algorithm::HS256);
            validation.validate_exp = true;
            decode::<Claims>(token, &key, &validation)
                .map_err(|e| format!("HS256 decode error: {}", e))?
        }
        _ => return Err("Unsupported algorithm".to_string()),
    };

    Ok(claims.claims)
}

async fn get_tenant_data(
    req: HttpRequest,
    state: web::Data<AppState>,
) -> HttpResponse {
    let auth_header = match req.headers().get("Authorization") {
        Some(h) => h.to_str().unwrap_or(""),
        None => return HttpResponse::Unauthorized().json("Missing auth"),
    };

    let token = auth_header.trim_start_matches("Bearer ");
    let claims = match decode_token(token, &state) {
        Ok(c) => c,
        Err(e) => return HttpResponse::Unauthorized().json(e),
    };

    // Set tenant context for RLS and query data
    let result = sqlx::query_as::<_, (String, String, i64)>(
        "SELECT id, data, amount FROM tenant_records WHERE tenant_id = $1"
    )
    .bind(&claims.tenant_id)
    .fetch_all(state.db_pool.as_ref())
    .await;

    match result {
        Ok(rows) => HttpResponse::Ok().json(rows),
        Err(e) => HttpResponse::InternalServerError().json(format!("DB error: {}", e)),
    }
}

async fn get_all_tenants(
    req: HttpRequest,
    state: web::Data<AppState>,
) -> HttpResponse {
    let auth_header = match req.headers().get("Authorization") {
        Some(h) => h.to_str().unwrap_or(""),
        None => return HttpResponse::Unauthorized().json("Missing auth"),
    };

    let token = auth_header.trim_start_matches("Bearer ");
    let claims = match decode_token(token, &state) {
        Ok(c) => c,
        Err(e) => return HttpResponse::Unauthorized().json(e),
    };

    if claims.role != "admin" {
        return HttpResponse::Forbidden().json("Admin only");
    }

    // Admin endpoint - queries across tenants
    let result = sqlx::query_as::<_, (String, String, String, i64)>(
        "SELECT tenant_id, id, data, amount FROM tenant_records"
    )
    .fetch_all(state.db_pool.as_ref())
    .await;

    match result {
        Ok(rows) => HttpResponse::Ok().json(rows),
        Err(e) => HttpResponse::InternalServerError().json(format!("DB error: {}", e)),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let database_url = env::var("DATABASE_URL").expect("DATABASE_URL required");
    let jwt_secret = env::var("JWT_SECRET").expect("JWT_SECRET required");
    let rsa_pub = std::fs::read(env::var("RSA_PUB_KEY_PATH").unwrap_or("./pub.pem".into()))
        .expect("RSA public key file required");

    let pool = PgPoolOptions::new()
        .max_connections(5)
        .connect(&database_url)
        .await
        .expect("Failed to create pool");

    let state = web::Data::new(AppState {
        db_pool: pool,
        jwt_secret,
        rsa_public_key: rsa_pub,
    });

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .route("/api/tenant/data", web::get().to(get_tenant_data))
            .route("/api/admin/tenants", web::get().to(get_all_tenants))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
